<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Code Line Counter','description'=>'Count total, blank and non-empty lines in source code.','url'=>'https://smarttoolz.in/tools/code-line-counter/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>Code Line Counter</h1><p>Count lines in any source code.</p></section><section class="tool-workspace"><div class="tool-panel"><textarea id="i" rows="14" placeholder="Paste code..."></textarea><button id="go" class="tool-btn">Count Lines</button><p id="o"></p></div></section></main><script>go.onclick=()=>{let a=i.value.split(/\r?\n/),n=a.filter(x=>x.trim()).length;o.textContent=`Total: ${a.length} · Non-empty: ${n} · Blank: ${a.length-n}`}</script><?php smarttoolz_tool_page_end(); ?>